# Splits of combined events into single events.
# SPLITS[old_id] = list of parts. Part 0 keeps the old id (so old links/bookmarks still work).
# Each part: full fields. Routing of existing links/story membership:
#   cin  = old heads of cause events whose link should attach to THIS part (default: part 0)
#   cout = old heads of effect events whose link should come from THIS part (default: part 0)
#   arcs = story ids for this part (default: all of the old event's stories)
# Region 'r' uses the new codes: na la eu me af sa ea se oc
def P(id, h, y, m, tier, c, who, where, lat, lon, hook, story, why, then, now, wk, **kw):
    d = dict(id=id, h=h, y=y, m=m, tier=tier, c=c, who=who, where=where, lat=lat, lon=lon,
             hook=hook, story=story, why=why, then=then, now=now, wk=wk)
    d.update(kw); return d

